<script setup lang="ts">
import {computed,reactive} from 'vue'
import type {VoucherRecord,VoucherGrouping,VoucherFilters} from '../voucher-analysis'
import {detailedVoucherReport,voucherMetrics,type DetailedVoucherGroup} from '../voucher-insights'
const props=defineProps<{records:VoucherRecord[];kind:'education'|'kindergarten';date:string;filters:VoucherFilters;summary:string}>()
const group=defineModel<VoucherGrouping>('group',{required:true}),subgroup=defineModel<VoucherGrouping|''>('subgroup',{required:true})
const emit=defineEmits<{drill:[name:string,ids:string[],month?:string]}>(),sections=reactive({status:true,finance:true,usage:true,operations:true,income:false})
const groups=[{key:'region',label:'Hudud'},{key:'district',label:'Tuman (shahar)'},{key:'organization',label:'Tashkilot'},{key:'status',label:'Holat'},{key:'month',label:'Hisobot oyi'},...(props.kind==='education'?[{key:'direction',label:'Yo‘nalish'},{key:'subject',label:'Fan'}]:[])]
const report=computed(()=>detailedVoucherReport(props.records,group.value,subgroup.value||null,props.date,props.filters)),total=computed(()=>voucherMetrics(props.records,props.date,props.filters))
type Key=keyof ReturnType<typeof voucherMetrics>
const columns=computed(()=>[{key:'vouchers',label:'Vaucherlar',section:'core'},{key:'children',label:'Bolalar',section:'core'},{key:'families',label:'Oilalar',section:'core'},...sections.status?[{key:'waiting',label:'Kutilmoqda',section:'status'},{key:'active',label:'Faollashtirilgan',section:'status'},{key:'ended',label:'Muddati yakunlangan',section:'status'}]:[],...sections.finance?[{key:'amount',label:'Xizmat to‘lovi',section:'finance'},...props.kind==='education'?[{key:'travel',label:'Yo‘lkira to‘lovi',section:'finance'}]:[]]:[],...sections.usage?[{key:'reported',label:'Ma’lum / jami oylar',section:'usage'},{key:'missingMonths',label:'Ma’lumoti yo‘q oylar',section:'usage'},{key:'coverage',label:'Qamrov %',section:'usage'},{key:'usage',label:'Foydalanish %',section:'usage'},{key:'low',label:'Past foydalanish',section:'usage'}]:[],...sections.operations?[{key:'changed',label:'O‘tish bo‘lgan',section:'operations'},{key:'ending',label:'30 kunda tugaydi',section:'operations'},...props.kind==='kindergarten'?[{key:'attendance',label:'Davomat (kun)',section:'operations'}]:[]]:[],...sections.income?[{key:'incomeUp',label:'Daromad o‘sgan',section:'income'},{key:'incomeDown',label:'Daromad kamaygan',section:'income'},{key:'incomeUnknown',label:'Daromad noma’lum',section:'income'}]:[]].map(c=>({...c,key:c.key as Key})))
const format=(key:Key,n:number|null)=>n===null?'—':key==='amount'||key==='travel'?n.toLocaleString('uz-UZ')+' so‘m':key==='coverage'||key==='usage'?n+'%':n
function open(row:DetailedVoucherGroup,key:Key){let ids=row.ids;if(['waiting','active','ended'].includes(key)){const status=key==='waiting'?'Kutilmoqda':key==='active'?'Faollashtirilgan':'Muddati yakunlangan';ids=props.records.filter(r=>ids.includes(r.id)&&r.status===status).map(r=>r.id)}emit('drill',(row.parent?row.parent+' / ':'')+row.name,ids,row.month)}
</script>
<template>
<section class="voucher-report voucher-print-surface voucher-rich-report" aria-label="Vaucherlar hisoboti">
<div class="voucher-report-toolbar"><label>Guruhlash<select v-model="group"><option v-for="g in groups" :key="g.key" :value="g.key">{{ g.label }}</option></select></label><label>Ichki guruh<select v-model="subgroup"><option value="">Guruhlanmasin</option><option v-for="g in groups.filter(g=>g.key!==group)" :key="g.key" :value="g.key">{{ g.label }}</option></select></label><span>{{ date }} holatiga</span></div>
<div class="vr-sections vi-no-print" aria-label="Hisobot ustunlari"><label><input v-model="sections.status" type="checkbox" /> Holatlar</label><label><input v-model="sections.finance" type="checkbox" /> Mablag‘lar</label><label><input v-model="sections.usage" type="checkbox" /> Foydalanish va qamrov</label><label><input v-model="sections.operations" type="checkbox" /> Monitoring</label><label><input v-model="sections.income" type="checkbox" /> Daromad</label></div>
<p v-if="summary" class="voucher-report-note">{{ summary }}</p>
<div class="kg-table"><table><thead><tr><th>Guruh</th><th v-for="c in columns" :key="c.key">{{ c.label }}</th></tr></thead><tbody><tr class="voucher-report-total"><td>JAMI</td><td v-for="c in columns" :key="c.key">{{ c.key==='reported'?total.reported+' / '+total.expected:format(c.key,total[c.key]) }}</td></tr><tr v-for="r in report" :key="r.key" :class="r.level?'vr-subrow':'vr-parent'"><td><button @click="emit('drill',(r.parent?r.parent+' / ':'')+r.name,r.ids,r.month)">{{ r.level?'↳ ':'' }}{{ r.name }}</button></td><td v-for="c in columns" :key="c.key" :class="c.key==='missingMonths'&&r.metrics.missingMonths?'warning':c.key==='coverage'&&r.metrics.coverage!==null?(r.metrics.coverage<70?'danger':r.metrics.coverage<100?'warning':'good'):''"><button v-if="['vouchers','children','waiting','active','ended'].includes(c.key)" @click="open(r,c.key)">{{ format(c.key,r.metrics[c.key]) }}</button><template v-else>{{ c.key==='reported'?r.metrics.reported+' / '+r.metrics.expected:format(c.key,r.metrics[c.key]) }}</template></td></tr><tr v-if="!report.length"><td :colspan="columns.length+1">Ma’lumot topilmadi.</td></tr></tbody></table></div>
<p class="voucher-report-note">Foydalanish = to‘lovli / ma’lum yakunlangan oylar. Qamrov = ma’lum / jami yakunlangan oylar. Holatlar {{ date }} sanasiga; mablag‘lar tanlangan davr bo‘yicha.</p><p class="voucher-report-note">Tashkilot va fan joriy biriktirish bo‘yicha. JAMI noyob vaucher, bola va oilalar bo‘yicha qayta hisoblanadi; ichki guruhlar yoki takroriy oilaviy summalar qo‘shib jamlanmaydi.</p>
</section>
</template>
